<?php
require_once __DIR__ . '/../../../config/db.php';
require_once __DIR__ . '/../../../config/app.php';
require_once __DIR__ . '/../../../utils/csrf.php';
require_once __DIR__ . '/../../../utils/csrf_sf.php';
require_once __DIR__ . '/../../../utils/mileage.php';
$userId=(int)($_SESSION['user']['id']??0);$orgId=request_client_org_id();
try{$o=$pdo->prepare('SELECT id,label,is_default FROM user_mileage_origins WHERE user_id=? ORDER BY is_default DESC,label');$o->execute([$userId]);$origins=$o->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$origins=[];}
try{$l=$pdo->prepare('SELECT s.*,c.name client_name FROM service_locations s LEFT JOIN clients c ON c.id=s.client_id WHERE s.archived=0 AND (?=0 OR s.organization_id=?) ORDER BY s.name');$l->execute([$orgId,$orgId]);$locations=$l->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$locations=[];}
try{$d=$pdo->prepare('SELECT d.*,o.label origin_label,s.name location_name FROM travel_distance_cache d JOIN user_mileage_origins o ON o.id=d.origin_id JOIN service_locations s ON s.id=d.service_location_id WHERE o.user_id=? ORDER BY s.name');$d->execute([$userId]);$distances=$d->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$distances=[];}
try{$r=$pdo->prepare('SELECT r.*,c.name client_name FROM travel_billing_rules r JOIN clients c ON c.id=r.client_id WHERE r.scope_type="client" AND (?=0 OR r.organization_id=?) ORDER BY c.name');$r->execute([$orgId,$orgId]);$clientRules=$r->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$clientRules=[];}
$clients=$pdo->query('SELECT id,name FROM clients WHERE archived=0 ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);
$token=csrf_sf_token('mileage_profile');$legacy=csrf_token();
?>
<section><div class="page-head"><div><h2>Mileage Setup</h2><p class="muted">Private billing origins, reusable service locations, and saved one-way pricing distances.</p></div><a class="btn" href="/?page=financial/mileage-list">Back to Mileage</a></div>
<?php if(!empty($_GET['saved'])): ?><div class="alert alert-success">Mileage setup saved.</div><?php endif; ?><?php if(!empty($_GET['error'])): ?><div class="alert alert-danger"><?php echo htmlspecialchars((string)$_GET['error']); ?></div><?php endif; ?>
<div class="grid grid-2" style="align-items:start">
 <div class="card"><h3>My private billing origins</h3><p class="muted">The exact address is encrypted. Client documents use the saved distance and do not expose this address.</p><ul><?php foreach($origins as $x): ?><li><?php echo htmlspecialchars($x['label']); ?><?php echo !empty($x['is_default'])?' (default)':''; ?></li><?php endforeach; ?><?php if(!$origins): ?><li class="muted">No origin configured.</li><?php endif; ?></ul><form method="post" action="/?page=financial/mileage-profile-handler" style="display:grid;gap:8px"><input type="hidden" name="_token" value="<?php echo htmlspecialchars($token); ?>"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($legacy); ?>"><input type="hidden" name="action" value="save_origin"><input class="input" name="label" required placeholder="Label, such as Home office"><input class="input" name="address_line1" required placeholder="Street address"><div class="grid grid-2"><input class="input" name="city" required placeholder="City"><input class="input" name="state" required placeholder="State"></div><input class="input" name="postal_code" required placeholder="Postal code"><label><input type="checkbox" name="is_default" value="1" checked> Use as my default billing origin</label><button class="btn btn-primary">Save encrypted origin</button></form></div>
 <div class="card"><h3>Service locations</h3><ul><?php foreach($locations as $x): ?><li><?php echo htmlspecialchars($x['name']); ?><?php echo $x['client_name']?' — '.htmlspecialchars($x['client_name']):''; ?></li><?php endforeach; ?><?php if(!$locations): ?><li class="muted">No saved service locations.</li><?php endif; ?></ul><form method="post" action="/?page=financial/mileage-profile-handler" style="display:grid;gap:8px"><input type="hidden" name="_token" value="<?php echo htmlspecialchars($token); ?>"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($legacy); ?>"><input type="hidden" name="action" value="save_location"><select class="input" name="client_id" required><option value="">Choose client</option><?php foreach($clients as $c): ?><option value="<?php echo (int)$c['id']; ?>"><?php echo htmlspecialchars($c['name']); ?></option><?php endforeach; ?></select><input class="input" name="name" required placeholder="Location name"><input class="input" name="address_line1" placeholder="Street address"><div class="grid grid-2"><input class="input" name="city" placeholder="City"><input class="input" name="state" placeholder="State"></div><input class="input" name="postal_code" placeholder="Postal code"><button class="btn btn-primary">Save service location</button></form></div>
</div>
<div class="card" style="margin-top:18px"><h3>Saved origin-to-location distances</h3><div class="pa-table-wrap"><table class="pa-table"><thead><tr><th>Origin</th><th>Service location</th><th>One-way miles</th></tr></thead><tbody><?php foreach($distances as $x): ?><tr><td><?php echo htmlspecialchars($x['origin_label']); ?></td><td><?php echo htmlspecialchars($x['location_name']); ?></td><td><?php echo number_format((float)$x['one_way_miles'],3); ?></td></tr><?php endforeach; ?><?php if(!$distances): ?><tr><td colspan="3" class="muted">No distances saved.</td></tr><?php endif; ?></tbody></table></div><form method="post" action="/?page=financial/mileage-profile-handler" class="grid grid-3" style="margin-top:12px" data-route-distance-form><input type="hidden" name="_token" value="<?php echo htmlspecialchars($token); ?>"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($legacy); ?>"><input type="hidden" name="action" value="save_distance"><select class="input" name="origin_id" required><option value="">Billing origin</option><?php foreach($origins as $x): ?><option value="<?php echo (int)$x['id']; ?>"><?php echo htmlspecialchars($x['label']); ?></option><?php endforeach; ?></select><select class="input" name="service_location_id" required><option value="">Service location</option><?php foreach($locations as $x): ?><option value="<?php echo (int)$x['id']; ?>"><?php echo htmlspecialchars($x['name']); ?></option><?php endforeach; ?></select><input class="input" type="number" min="0.001" step="0.001" name="one_way_miles" required placeholder="One-way miles"><div style="display:flex;gap:8px"><button class="btn btn-primary">Save distance</button><?php if(!empty($appConfig['address_route_assistance_enabled'])): ?><button type="button" class="btn" data-estimate-route>Suggest with Google</button><?php endif; ?></div><small class="muted" data-route-result></small></form></div>
<div class="card" style="margin-top:18px"><h3>Client travel defaults</h3><p class="muted">These override organization workflow defaults. A quote or contract can override them again, and a mileage charge can be adjusted for one trip.</p><div class="pa-table-wrap"><table class="pa-table"><thead><tr><th>Client</th><th>Method</th><th>Rate</th><th>Included miles</th><th>Directions</th></tr></thead><tbody><?php foreach($clientRules as $x): ?><tr><td><?php echo htmlspecialchars($x['client_name']); ?></td><td><?php echo htmlspecialchars(mileage_charge_method_label($x['charge_method'])); ?></td><td><?php echo $x['charge_method']==='fixed_fee'?'$'.number_format((float)$x['fixed_amount'],2):'$'.number_format((float)$x['mileage_rate'],4).'/mi'; ?></td><td><?php echo number_format((float)$x['included_miles'],3); ?></td><td><?php echo !empty($x['charge_return'])?'Outbound and return':'One direction'; ?></td></tr><?php endforeach; ?><?php if(!$clientRules): ?><tr><td colspan="5" class="muted">No client-specific defaults.</td></tr><?php endif; ?></tbody></table></div><form method="post" action="/?page=financial/mileage-profile-handler" style="display:grid;gap:10px;margin-top:12px"><input type="hidden" name="_token" value="<?php echo htmlspecialchars($token); ?>"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars($legacy); ?>"><input type="hidden" name="action" value="save_client_rule"><div class="grid grid-2"><select class="input" name="client_id" required><option value="">Choose client</option><?php foreach($clients as $c): ?><option value="<?php echo (int)$c['id']; ?>"><?php echo htmlspecialchars($c['name']); ?></option><?php endforeach; ?></select><select class="input" name="travel_charge_method"><option value="origin_distance">Billing origin to service location</option><option value="actual_trip">Approved actual trip distance</option><option value="fixed_fee">Fixed travel fee</option><option value="none">No client travel charge</option></select></div><div class="grid grid-3"><input class="input" type="number" min="0" step="0.0001" name="travel_mileage_rate" value="<?php echo htmlspecialchars((string)($appConfig['default_mileage_rate']??0.670)); ?>" placeholder="Rate per mile"><input class="input" type="number" min="0" step="0.001" name="travel_included_miles" value="<?php echo htmlspecialchars((string)($appConfig['default_mileage_included_miles']??0)); ?>" placeholder="Included miles"><input class="input" type="number" min="0" step="0.01" name="travel_fixed_amount" value="0.00" placeholder="Fixed fee"></div><div class="grid grid-2"><select class="input" name="travel_origin_id"><option value="">Default billing origin</option><?php foreach($origins as $x): ?><option value="<?php echo (int)$x['id']; ?>"><?php echo htmlspecialchars($x['label']); ?></option><?php endforeach; ?></select><select class="input" name="travel_service_location_id"><option value="">Default service location</option><?php foreach($locations as $x): ?><option value="<?php echo (int)$x['id']; ?>"><?php echo htmlspecialchars($x['name']); ?></option><?php endforeach; ?></select></div><label><input type="checkbox" name="travel_charge_return" value="1"> Charge outbound and return travel by default</label><textarea class="input" name="travel_terms_text" rows="2" placeholder="Optional client travel terms"></textarea><button class="btn btn-primary">Save client default</button></form></div>
</section>
